use crate::error::*;
use reqwest::multipart;
use serde::{Deserialize, Serialize};
use std::collections::HashMap;
use std::path::Path;
use std::time::Duration;

#[derive(Clone)]
pub struct PaymentMethodFingerprintIdApiClient {
    client: reqwest::Client,
    endpoint: String,
    api_key: String,
    headers: HashMap<String, String>,
    retry_count: usize,
    retry_backoff: Duration,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct PaymentMethodFingerprintIdUploadOutcome {
    pub attempts: usize,
    pub http_status: Option<u16>,
    pub headers: HashMap<String, String>,
    pub body: serde_json::Value,
    pub transport_error: Option<String>,
}

impl PaymentMethodFingerprintIdApiClient {
    pub fn new(
        endpoint: String,
        api_key: String,
        headers: HashMap<String, String>,
        timeout: Duration,
        retry_count: usize,
        retry_backoff: Duration,
    ) -> Result<Self> {
        let client = reqwest::Client::builder()
            .timeout(timeout)
            .pool_max_idle_per_host(10)
            .pool_idle_timeout(Duration::from_secs(90))
            .build()?;

        Ok(Self {
            client,
            endpoint,
            api_key,
            headers,
            retry_count,
            retry_backoff,
        })
    }

    pub fn endpoint(&self) -> &str {
        &self.endpoint
    }

    pub async fn upload_batch_file(
        &self,
        batch_file: &Path,
        file_name: &str,
    ) -> PaymentMethodFingerprintIdUploadOutcome {
        let bytes = match tokio::fs::read(batch_file).await {
            Ok(bytes) => bytes,
            Err(error) => {
                return PaymentMethodFingerprintIdUploadOutcome {
                    attempts: 0,
                    http_status: None,
                    headers: HashMap::new(),
                    body: serde_json::Value::Null,
                    transport_error: Some(error.to_string()),
                };
            }
        };

        let max_attempts = self.retry_count + 1;
        let mut last_error = None;

        for attempt in 1..=max_attempts {
            let form = multipart::Form::new().part(
                "file",
                multipart::Part::bytes(bytes.clone())
                    .file_name(file_name.to_string())
                    .mime_str("text/csv")
                    .unwrap_or_else(|_| multipart::Part::bytes(bytes.clone())),
            );

            let mut request = self
                .client
                .post(&self.endpoint)
                .header("api-key", &self.api_key)
                .multipart(form);

            for (key, value) in &self.headers {
                request = request.header(key.as_str(), value.as_str());
            }

            let response = request.send().await;

            match response {
                Ok(response) => {
                    let status = response.status();
                    let mut headers = HashMap::new();
                    for (key, value) in response.headers() {
                        if let Ok(value_str) = value.to_str() {
                            headers.insert(key.to_string(), value_str.to_string());
                        }
                    }

                    let response_text = response.text().await.unwrap_or_default();
                    let body = serde_json::from_str(&response_text)
                        .unwrap_or_else(|_| serde_json::Value::String(response_text));

                    if status.is_server_error() && attempt < max_attempts {
                        tokio::time::sleep(self.retry_backoff).await;
                        continue;
                    }

                    return PaymentMethodFingerprintIdUploadOutcome {
                        attempts: attempt,
                        http_status: Some(status.as_u16()),
                        headers,
                        body,
                        transport_error: None,
                    };
                }
                Err(error) => {
                    last_error = Some(error.to_string());
                    if attempt < max_attempts {
                        tokio::time::sleep(self.retry_backoff).await;
                    }
                }
            }
        }

        PaymentMethodFingerprintIdUploadOutcome {
            attempts: max_attempts,
            http_status: None,
            headers: HashMap::new(),
            body: serde_json::Value::Null,
            transport_error: last_error,
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use std::fs;
    use tokio::io::{AsyncReadExt, AsyncWriteExt};
    use tokio::net::TcpListener;

    #[tokio::test]
    async fn uploads_batch_with_api_key_header_and_file_part() {
        let listener = match TcpListener::bind("127.0.0.1:0").await {
            Ok(listener) => listener,
            Err(error) if error.kind() == std::io::ErrorKind::PermissionDenied => {
                eprintln!("Skipping local HTTP mock test: {}", error);
                return;
            }
            Err(error) => panic!("failed to bind local test server: {}", error),
        };
        let addr = listener.local_addr().unwrap();

        let server = tokio::spawn(async move {
            let (mut socket, _) = listener.accept().await.unwrap();
            let mut buffer = vec![0; 8192];
            let mut read = socket.read(&mut buffer).await.unwrap();

            let headers_end = loop {
                if let Some(pos) = buffer[..read].windows(4).position(|w| w == b"\r\n\r\n") {
                    break pos + 4;
                }
                let next = socket.read(&mut buffer[read..]).await.unwrap();
                if next == 0 {
                    break read;
                }
                read += next;
            };

            let request_head = String::from_utf8_lossy(&buffer[..headers_end]).to_string();
            let content_length = request_head
                .lines()
                .find_map(|line| line.strip_prefix("Content-Length: "))
                .and_then(|value| value.trim().parse::<usize>().ok())
                .unwrap_or(0);

            let mut body = buffer[headers_end..read].to_vec();
            while body.len() < content_length {
                let mut chunk = vec![0; content_length - body.len()];
                let next = socket.read(&mut chunk).await.unwrap();
                if next == 0 {
                    break;
                }
                body.extend_from_slice(&chunk[..next]);
            }

            let response_body = concat!(
                "{\"total_rows\":1,\"successful_count\":1,\"failed_count\":0,",
                "\"results\":[{\"row_number\":2,\"merchant_id\":\"m1\",",
                "\"payment_method_id\":\"pm_1\",\"old_fingerprint_id\":\"fp_old\",",
                "\"new_fingerprint_id\":\"fp_new\",\"migration_status\":\"Success\"}]}"
            );
            let response = format!(
                "HTTP/1.1 200 OK\r\nContent-Type: application/json\r\nContent-Length: {}\r\n\r\n{}",
                response_body.len(),
                response_body
            );
            socket.write_all(response.as_bytes()).await.unwrap();

            (request_head, String::from_utf8_lossy(&body).to_string())
        });

        let dir = std::env::temp_dir().join(format!(
            "migratus-fingerprint-upload-test-{}",
            chrono::Utc::now().timestamp_nanos_opt().unwrap()
        ));
        fs::create_dir_all(&dir).unwrap();
        let batch_path = dir.join("batch_0001.csv");
        fs::write(&batch_path, "merchant_id,payment_method_id\nm1,pm_1\n").unwrap();

        let mut headers = HashMap::new();
        headers.insert("x-feature".to_string(), "integ-custom".to_string());

        let client = PaymentMethodFingerprintIdApiClient::new(
            format!("http://{}/payment_methods/fingerprint/migrate-batch", addr),
            "secret".to_string(),
            headers,
            Duration::from_secs(5),
            0,
            Duration::from_millis(1),
        )
        .unwrap();

        let outcome = client
            .upload_batch_file(&batch_path, "batch_0001.csv")
            .await;
        let (request_head, body) = server.await.unwrap();

        assert_eq!(outcome.http_status, Some(200));
        assert!(
            request_head.starts_with("POST /payment_methods/fingerprint/migrate-batch HTTP/1.1")
        );
        assert!(request_head.contains("api-key: secret"));
        assert!(request_head.contains("x-feature: integ-custom"));
        assert!(body.contains("name=\"file\""));
        assert!(body.contains("filename=\"batch_0001.csv\""));
        assert!(body.contains("merchant_id,payment_method_id"));

        fs::remove_dir_all(dir).unwrap();
    }
}

use crate::domain::{
    records::{Batch, FailedMigration, MigrationFailureReason, SuccessfulMigration},
    types::{CustomerId, PaymentMethodId},
};
use crate::error::*;
use reqwest::multipart;
use serde::{Deserialize, Serialize};

pub struct ApiClient {
    client: reqwest::Client,
    endpoint: String,
    api_key: String,
    merchant_id: String,
    merchant_connector_ids: Option<String>,
}

impl ApiClient {
    pub fn new(
        endpoint: String,
        api_key: String,
        merchant_id: String,
        merchant_connector_ids: Option<String>,
        timeout: std::time::Duration,
    ) -> Result<Self> {
        let client = reqwest::Client::builder()
            .timeout(timeout)
            .pool_max_idle_per_host(10)
            .pool_idle_timeout(std::time::Duration::from_secs(90))
            .build()?;

        Ok(Self {
            client,
            endpoint,
            api_key,
            merchant_id,
            merchant_connector_ids,
        })
    }

    pub async fn migrate_batch(&self, batch: &Batch) -> Result<BatchMigrationResponse> {
        let (response, _headers) = self.migrate_batch_with_headers(batch).await?;
        Ok(response)
    }

    pub async fn migrate_batch_with_headers(
        &self,
        batch: &Batch,
    ) -> Result<(
        BatchMigrationResponse,
        std::collections::HashMap<String, String>,
    )> {
        let csv_data = self.batch_to_csv(batch)?;

        let mut form = multipart::Form::new()
            .text("merchant_id", self.merchant_id.clone())
            .part(
                "file",
                multipart::Part::bytes(csv_data)
                    .file_name(format!("batch_{}.csv", batch.batch_number.value()))
                    .mime_str("text/csv")?,
            );

        if let Some(mca_ids) = &self.merchant_connector_ids {
            form = form.text("merchant_connector_ids", mca_ids.clone());
        }

        let response = self
            .client
            .post(&self.endpoint)
            .header("api-key", &self.api_key)
            .multipart(form)
            .send()
            .await?;

        // Capture headers
        let mut headers_map = std::collections::HashMap::new();
        for (key, value) in response.headers() {
            if let Ok(value_str) = value.to_str() {
                headers_map.insert(key.to_string(), value_str.to_string());
            }
        }

        let status = response.status();

        if status.is_success() {
            let records: Vec<ApiMigrationRecord> = response.json().await?;
            Ok((BatchMigrationResponse::Success(records), headers_map))
        } else {
            let status_code = status.as_u16();
            let message = response
                .text()
                .await
                .unwrap_or_else(|e| format!("Failed to read error response: {}", e));
            Ok((
                BatchMigrationResponse::Error {
                    status: status_code,
                    message,
                },
                headers_map,
            ))
        }
    }

    fn batch_to_csv(&self, batch: &Batch) -> Result<Vec<u8>> {
        let mut wtr = csv::Writer::from_writer(vec![]);

        if let Some(first_record) = batch.records.first() {
            let headers: Vec<String> = first_record.data.keys().cloned().collect();
            wtr.write_record(&headers)?;

            for record in &batch.records {
                let values: Vec<String> = headers
                    .iter()
                    .map(|h| record.data.get(h).cloned().unwrap_or_default())
                    .collect();
                wtr.write_record(&values)?;
            }
        }

        wtr.into_inner()
            .map_err(|e| MigrationError::InternalError(format!("CSV writer error: {}", e)))
    }

    pub fn parse_response(
        &self,
        batch: &Batch,
        response: BatchMigrationResponse,
    ) -> BatchMigrationResult {
        match response {
            BatchMigrationResponse::Success(records) => {
                let mut successful = Vec::new();
                let mut failed = Vec::new();

                for record in records {
                    let line_num = record.line_number.unwrap_or(1) as usize;

                    if record.migration_status == "Success" {
                        if let (Some(pm_id), Some(cust_id)) =
                            (&record.payment_method_id, &record.customer_id)
                        {
                            let original_data = batch
                                .records
                                .get(line_num.saturating_sub(1))
                                .map(|r| r.data.clone())
                                .unwrap_or_default();

                            successful.push(SuccessfulMigration {
                                line_number: crate::domain::types::LineNumber::new(line_num),
                                batch_number: batch.batch_number,
                                original_data,
                                payment_method_id: PaymentMethodId::new(pm_id.clone()),
                                customer_id: CustomerId::new(cust_id.clone()),
                                migration_status: record.migration_status.clone(),
                                metadata: crate::domain::records::MigrationMetadata {
                                    card_migrated: record.card_migrated,
                                    network_token_migrated: record
                                        .network_token_migrated
                                        .unwrap_or(false),
                                    connector_mandate_details_migrated: record
                                        .connector_mandate_details_migrated
                                        .unwrap_or(false),
                                    network_transaction_id_migrated: record
                                        .network_transaction_id_migrated
                                        .unwrap_or(false),
                                },
                                payment_method: record.payment_method.clone(),
                                payment_method_type: record.payment_method_type.clone(),
                                card_number_masked: record.card_number_masked.clone(),
                            });
                        }
                    } else {
                        let original_data = batch
                            .records
                            .get(line_num.saturating_sub(1))
                            .map(|r| r.data.clone())
                            .unwrap_or_default();

                        failed.push(FailedMigration {
                            line_number: crate::domain::types::LineNumber::new(line_num),
                            batch_number: batch.batch_number,
                            original_data,
                            failure_reason: MigrationFailureReason::RecordLevelFailure(
                                record.migration_error.unwrap_or_default(),
                            ),
                        });
                    }
                }

                BatchMigrationResult { successful, failed }
            }
            BatchMigrationResponse::Error { status, message } => {
                let failed: Vec<FailedMigration> = batch
                    .records
                    .iter()
                    .enumerate()
                    .map(|(i, record)| FailedMigration {
                        line_number: crate::domain::types::LineNumber::new(i + 1),
                        batch_number: batch.batch_number,
                        original_data: record.data.clone(),
                        failure_reason: MigrationFailureReason::ApiError {
                            status,
                            message: message.clone(),
                        },
                    })
                    .collect();

                BatchMigrationResult {
                    successful: Vec::new(),
                    failed,
                }
            }
        }
    }
}

#[derive(Debug, Serialize, Deserialize)]
pub struct ApiMigrationRecord {
    pub line_number: Option<i64>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub payment_method_id: Option<String>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub payment_method: Option<String>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub payment_method_type: Option<String>,
    pub customer_id: Option<String>,
    pub migration_status: String,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub migration_error: Option<String>,
    pub card_number_masked: Option<String>,
    pub card_migrated: Option<bool>,
    pub network_token_migrated: Option<bool>,
    pub connector_mandate_details_migrated: Option<bool>,
    pub network_transaction_id_migrated: Option<bool>,
}

#[derive(Debug, Serialize, Deserialize)]
#[serde(untagged)]
pub enum BatchMigrationResponse {
    Success(Vec<ApiMigrationRecord>),
    Error { status: u16, message: String },
}

pub struct BatchMigrationResult {
    pub successful: Vec<SuccessfulMigration>,
    pub failed: Vec<FailedMigration>,
}

pub mod customer_global_id;
pub mod payment_method_fingerprint_id;
pub mod update;

pub use customer_global_id::{CustomerGlobalIdApiClient, CustomerGlobalIdUploadOutcome};
pub use payment_method_fingerprint_id::{
    PaymentMethodFingerprintIdApiClient, PaymentMethodFingerprintIdUploadOutcome,
};
pub use update::{ApiUpdateResponse, BatchUpdateResponse, UpdateApiClient};

use crate::domain::update::{
    FailedUpdate, SuccessfulUpdate, UpdateBatch, UpdateFailureReason, UpdateMetadata,
};
use crate::error::*;
use reqwest::multipart;
use serde::{Deserialize, Serialize};

pub struct UpdateApiClient {
    client: reqwest::Client,
    endpoint: String,
    api_key: String,
    merchant_id: String,
    merchant_connector_ids: Option<String>,
}

impl UpdateApiClient {
    pub fn new(
        endpoint: String,
        api_key: String,
        merchant_id: String,
        merchant_connector_ids: Option<String>,
        timeout: std::time::Duration,
    ) -> Result<Self> {
        let client = reqwest::Client::builder()
            .timeout(timeout)
            .pool_max_idle_per_host(10)
            .pool_idle_timeout(std::time::Duration::from_secs(90))
            .build()?;

        Ok(Self {
            client,
            endpoint,
            api_key,
            merchant_id,
            merchant_connector_ids,
        })
    }

    pub async fn update_batch(&self, batch: &UpdateBatch) -> Result<BatchUpdateResponse> {
        let (response, _headers) = self.update_batch_with_headers(batch).await?;
        Ok(response)
    }

    pub async fn update_batch_with_headers(
        &self,
        batch: &UpdateBatch,
    ) -> Result<(
        BatchUpdateResponse,
        std::collections::HashMap<String, String>,
    )> {
        let csv_data = self.batch_to_csv(batch)?;

        let mut form = multipart::Form::new()
            .text("merchant_id", self.merchant_id.clone())
            .part(
                "file",
                multipart::Part::bytes(csv_data)
                    .file_name(format!("batch_{}.csv", batch.batch_number.value()))
                    .mime_str("text/csv")?,
            );

        if let Some(mca_ids) = &self.merchant_connector_ids {
            form = form.text("merchant_connector_ids", mca_ids.clone());
        }

        let response = self
            .client
            .post(&self.endpoint)
            .header("api-key", &self.api_key)
            .multipart(form)
            .send()
            .await?;

        // Capture headers
        let mut headers_map = std::collections::HashMap::new();
        for (key, value) in response.headers() {
            if let Ok(value_str) = value.to_str() {
                headers_map.insert(key.to_string(), value_str.to_string());
            }
        }

        let status = response.status();

        if status.is_success() {
            let records: Vec<ApiUpdateResponse> = response.json().await?;
            Ok((BatchUpdateResponse::Success(records), headers_map))
        } else {
            let status_code = status.as_u16();
            let message = response
                .text()
                .await
                .unwrap_or_else(|e| format!("Failed to read error response: {}", e));
            Ok((
                BatchUpdateResponse::Error {
                    status: status_code,
                    message,
                },
                headers_map,
            ))
        }
    }

    fn batch_to_csv(&self, batch: &UpdateBatch) -> Result<Vec<u8>> {
        let mut wtr = csv::Writer::from_writer(vec![]);

        if let Some(first_record) = batch.records.first() {
            let headers: Vec<String> = first_record.data.keys().cloned().collect();
            wtr.write_record(&headers)?;

            for record in &batch.records {
                let values: Vec<String> = headers
                    .iter()
                    .map(|h| record.data.get(h).cloned().unwrap_or_default())
                    .collect();
                wtr.write_record(&values)?;
            }
        }

        wtr.into_inner()
            .map_err(|e| MigrationError::InternalError(format!("CSV writer error: {}", e)))
    }

    pub fn parse_response(
        &self,
        batch: &UpdateBatch,
        response: BatchUpdateResponse,
    ) -> BatchUpdateResult {
        match response {
            BatchUpdateResponse::Success(records) => {
                let mut successful = Vec::new();
                let mut failed = Vec::new();

                for record in records {
                    let line_num = record.line_number.unwrap_or(1) as usize;

                    if record.update_status == "Success" {
                        if let Some(pm_id) = &record.payment_method_id {
                            let original_data = batch
                                .records
                                .get(line_num.saturating_sub(1))
                                .map(|r| r.data.clone())
                                .unwrap_or_default();

                            successful.push(SuccessfulUpdate {
                                line_number: crate::domain::types::LineNumber::new(line_num),
                                batch_number: batch.batch_number,
                                original_data,
                                payment_method_id: crate::domain::types::PaymentMethodId::new(
                                    pm_id.clone(),
                                ),
                                update_status: record.update_status.clone(),
                                metadata: UpdateMetadata {
                                    updated_payment_method_data: record.updated_payment_method_data,
                                    connector_customer_updated: record.connector_customer.is_some(),
                                    connector_mandate_details_updated: record
                                        .connector_mandate_details
                                        .is_some(),
                                },
                            });
                        }
                    } else {
                        let original_data = batch
                            .records
                            .get(line_num.saturating_sub(1))
                            .map(|r| r.data.clone())
                            .unwrap_or_default();

                        failed.push(FailedUpdate {
                            line_number: crate::domain::types::LineNumber::new(line_num),
                            batch_number: batch.batch_number,
                            original_data,
                            failure_reason: UpdateFailureReason::RecordLevelFailure(
                                record.update_error.unwrap_or_default(),
                            ),
                        });
                    }
                }

                BatchUpdateResult { successful, failed }
            }
            BatchUpdateResponse::Error { status, message } => {
                let failed: Vec<FailedUpdate> = batch
                    .records
                    .iter()
                    .enumerate()
                    .map(|(i, record)| FailedUpdate {
                        line_number: crate::domain::types::LineNumber::new(i + 1),
                        batch_number: batch.batch_number,
                        original_data: record.data.clone(),
                        failure_reason: UpdateFailureReason::ApiError {
                            status,
                            message: message.clone(),
                        },
                    })
                    .collect();

                BatchUpdateResult {
                    successful: Vec::new(),
                    failed,
                }
            }
        }
    }
}

#[derive(Debug, Serialize, Deserialize)]
pub struct ApiUpdateResponse {
    pub payment_method_id: Option<String>,
    pub status: Option<String>,
    pub network_transaction_id: Option<String>,
    pub connector_mandate_details: Option<serde_json::Value>,
    pub update_status: String,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub update_error: Option<String>,
    pub updated_payment_method_data: Option<bool>,
    pub connector_customer: Option<serde_json::Value>,
    pub line_number: Option<i64>,
}

#[derive(Debug, Serialize, Deserialize)]
#[serde(untagged)]
pub enum BatchUpdateResponse {
    Success(Vec<ApiUpdateResponse>),
    Error { status: u16, message: String },
}

pub struct BatchUpdateResult {
    pub successful: Vec<SuccessfulUpdate>,
    pub failed: Vec<FailedUpdate>,
}

use crate::error::*;
use reqwest::multipart;
use serde::{Deserialize, Serialize};
use std::collections::HashMap;
use std::path::Path;
use std::time::Duration;

#[derive(Clone)]
pub struct CustomerGlobalIdApiClient {
    client: reqwest::Client,
    endpoint: String,
    admin_api_key: String,
    retry_count: usize,
    retry_backoff: Duration,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct CustomerGlobalIdUploadOutcome {
    pub attempts: usize,
    pub http_status: Option<u16>,
    pub headers: HashMap<String, String>,
    pub body: serde_json::Value,
    pub transport_error: Option<String>,
}

impl CustomerGlobalIdApiClient {
    pub fn new(
        endpoint: String,
        admin_api_key: String,
        timeout: Duration,
        retry_count: usize,
        retry_backoff: Duration,
    ) -> Result<Self> {
        let client = reqwest::Client::builder()
            .timeout(timeout)
            .pool_max_idle_per_host(10)
            .pool_idle_timeout(Duration::from_secs(90))
            .build()?;

        Ok(Self {
            client,
            endpoint,
            admin_api_key,
            retry_count,
            retry_backoff,
        })
    }

    pub fn endpoint(&self) -> &str {
        &self.endpoint
    }

    pub async fn upload_batch_file(
        &self,
        batch_file: &Path,
        file_name: &str,
    ) -> CustomerGlobalIdUploadOutcome {
        let bytes = match tokio::fs::read(batch_file).await {
            Ok(bytes) => bytes,
            Err(error) => {
                return CustomerGlobalIdUploadOutcome {
                    attempts: 0,
                    http_status: None,
                    headers: HashMap::new(),
                    body: serde_json::Value::Null,
                    transport_error: Some(error.to_string()),
                };
            }
        };

        let max_attempts = self.retry_count + 1;
        let mut last_error = None;

        for attempt in 1..=max_attempts {
            let form = multipart::Form::new().part(
                "file",
                multipart::Part::bytes(bytes.clone())
                    .file_name(file_name.to_string())
                    .mime_str("text/csv")
                    .unwrap_or_else(|_| multipart::Part::bytes(bytes.clone())),
            );

            let response = self
                .client
                .post(&self.endpoint)
                .header(
                    "Authorization",
                    format!("admin-api-key={}", self.admin_api_key),
                )
                .multipart(form)
                .send()
                .await;

            match response {
                Ok(response) => {
                    let status = response.status();
                    let mut headers = HashMap::new();
                    for (key, value) in response.headers() {
                        if let Ok(value_str) = value.to_str() {
                            headers.insert(key.to_string(), value_str.to_string());
                        }
                    }

                    let response_text = response.text().await.unwrap_or_default();
                    let body = serde_json::from_str(&response_text)
                        .unwrap_or_else(|_| serde_json::Value::String(response_text));

                    if status.is_server_error() && attempt < max_attempts {
                        tokio::time::sleep(self.retry_backoff).await;
                        continue;
                    }

                    return CustomerGlobalIdUploadOutcome {
                        attempts: attempt,
                        http_status: Some(status.as_u16()),
                        headers,
                        body,
                        transport_error: None,
                    };
                }
                Err(error) => {
                    last_error = Some(error.to_string());
                    if attempt < max_attempts {
                        tokio::time::sleep(self.retry_backoff).await;
                    }
                }
            }
        }

        CustomerGlobalIdUploadOutcome {
            attempts: max_attempts,
            http_status: None,
            headers: HashMap::new(),
            body: serde_json::Value::Null,
            transport_error: last_error,
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use std::fs;
    use tokio::io::{AsyncReadExt, AsyncWriteExt};
    use tokio::net::TcpListener;

    #[tokio::test]
    async fn uploads_batch_with_admin_auth_and_file_part() {
        let listener = match TcpListener::bind("127.0.0.1:0").await {
            Ok(listener) => listener,
            Err(error) if error.kind() == std::io::ErrorKind::PermissionDenied => {
                eprintln!("Skipping local HTTP mock test: {}", error);
                return;
            }
            Err(error) => panic!("failed to bind local test server: {}", error),
        };
        let addr = listener.local_addr().unwrap();

        let server = tokio::spawn(async move {
            let (mut socket, _) = listener.accept().await.unwrap();
            let mut buffer = vec![0; 8192];
            let mut read = socket.read(&mut buffer).await.unwrap();

            let headers_end = loop {
                if let Some(pos) = buffer[..read].windows(4).position(|w| w == b"\r\n\r\n") {
                    break pos + 4;
                }
                let next = socket.read(&mut buffer[read..]).await.unwrap();
                if next == 0 {
                    break read;
                }
                read += next;
            };

            let request_head = String::from_utf8_lossy(&buffer[..headers_end]).to_string();
            let content_length = request_head
                .lines()
                .find_map(|line| line.strip_prefix("Content-Length: "))
                .and_then(|value| value.trim().parse::<usize>().ok())
                .unwrap_or(0);

            let mut body = buffer[headers_end..read].to_vec();
            while body.len() < content_length {
                let mut chunk = vec![0; content_length - body.len()];
                let next = socket.read(&mut chunk).await.unwrap();
                if next == 0 {
                    break;
                }
                body.extend_from_slice(&chunk[..next]);
            }

            let response_body = concat!(
                "{\"updated_count\":1,\"skipped_count\":0,\"failed_count\":0,",
                "\"results\":[{\"status\":\"updated_null_id\"}]}"
            );
            let response = format!(
                "HTTP/1.1 200 OK\r\nContent-Type: application/json\r\nContent-Length: {}\r\n\r\n{}",
                response_body.len(),
                response_body
            );
            socket.write_all(response.as_bytes()).await.unwrap();

            (request_head, String::from_utf8_lossy(&body).to_string())
        });

        let dir = std::env::temp_dir().join(format!(
            "migratus-customer-upload-test-{}",
            chrono::Utc::now().timestamp_nanos_opt().unwrap()
        ));
        fs::create_dir_all(&dir).unwrap();
        let batch_path = dir.join("batch_0001.csv");
        fs::write(&batch_path, "merchant_id,customer_id\nm1,c1\n").unwrap();

        let client = CustomerGlobalIdApiClient::new(
            format!("http://{}/v2/customers/migrate/global-id", addr),
            "secret".to_string(),
            Duration::from_secs(5),
            0,
            Duration::from_millis(1),
        )
        .unwrap();

        let outcome = client
            .upload_batch_file(&batch_path, "batch_0001.csv")
            .await;
        let (request_head, body) = server.await.unwrap();

        assert_eq!(outcome.http_status, Some(200));
        assert!(request_head.starts_with("POST /v2/customers/migrate/global-id HTTP/1.1"));
        assert!(request_head.contains("Authorization: admin-api-key=secret"));
        assert!(body.contains("name=\"file\""));
        assert!(body.contains("filename=\"batch_0001.csv\""));
        assert!(body.contains("merchant_id,customer_id"));

        fs::remove_dir_all(dir).unwrap();
    }
}

